\[
\begin{aligned}
\nabla s
&=\sum_{i=0}^{3}\vec{\delta}_{i}\frac{\partial}{\partial x_i}s\\
&=\sum_{i=0}^{3}\vec{\delta}_{i}\frac{\partial s}{\partial x_i}\\
&=\vec{\delta}_{x}\frac{\partial s}{\partial x}+\vec{\delta}_{y}\frac{\partial s}{\partial y}+\vec{\delta}_{z}\frac{\partial s}{\partial z}
\end{aligned}
\]

\[
\begin{aligned}
\nabla\vec{v}
&=\sum_{i=0}^{3}\vec{\delta}_{i}\frac{\partial}{\partial x_i}\sum_{j=0}^{3}\vec{\delta}_{j}v_j\\
&=\sum_{i=0}^{3}\sum_{j=0}^{3}\vec{\delta}_{i}\frac{\partial}{\partial x_i}\vec{\delta}_{j}v_j\\
&=\sum_{i=0}^{3}\sum_{j=0}^{3}\vec{\delta}_{i}\frac{\partial(\vec{\delta}_{j}v_j)}{\partial x_i}\\
&=\sum_{i=0}^{3}\sum_{j=0}^{3}\vec{\delta}_{i}\vec{\delta}_{j}\frac{\partial v_j}{\partial x_i}\\
&=\vec{\delta}_{x}\vec{\delta}_{x}\frac{\partial v_x}{\partial x}+\vec{\delta}_{x}\vec{\delta}_{y}\frac{\partial v_y}{\partial x}+\vec{\delta}_{x}\vec{\delta}_{z}\frac{\partial v_z}{\partial x}\\
&\quad+\vec{\delta}_{y}\vec{\delta}_{x}\frac{\partial v_x}{\partial y}+\vec{\delta}_{y}\vec{\delta}_{y}\frac{\partial v_y}{\partial y}+\vec{\delta}_{y}\vec{\delta}_{z}\frac{\partial v_z}{\partial y}\\
&\quad+\vec{\delta}_{z}\vec{\delta}_{x}\frac{\partial v_x}{\partial z}+\vec{\delta}_{z}\vec{\delta}_{y}\frac{\partial v_y}{\partial z}+\vec{\delta}_{z}\vec{\delta}_{z}\frac{\partial v_z}{\partial z}
\end{aligned}
\]
